<template>
  <div class="analysis-page">
    <section class="page-head"><div><p class="eyebrow">AI OPERATIONS CENTER <span>数据洞察工作台</span></p><h1>评价分析与运营报告</h1><p>汇总用户评价、售后风险和高频咨询，快速找到下一步运营动作。</p></div><el-button class="refresh-btn" :loading="loading" @click="load"><el-icon><Refresh /></el-icon>刷新数据</el-button></section>
    <el-row :gutter="16" class="metrics"><el-col :xs="12" :sm="6"><div class="metric"><span class="metric-icon cyan">◎</span><div><small>分析记录</small><strong>{{ analysis.length }}</strong><em>条</em></div></div></el-col><el-col :xs="12" :sm="6"><div class="metric"><span class="metric-icon blue">▤</span><div><small>运营报告</small><strong>{{ reports.length }}</strong><em>份</em></div></div></el-col><el-col :xs="12" :sm="6"><div class="metric"><span class="metric-icon green">✓</span><div><small>评价样本</small><strong>{{ reviewCount }}</strong><em>条</em></div></div></el-col><el-col :xs="12" :sm="6"><div class="metric"><span class="metric-icon orange">?</span><div><small>数据状态</small><strong class="status">{{ analysis.length || reports.length ? '已更新' : '待生成' }}</strong></div></div></el-col></el-row>
    <el-row :gutter="18" class="content-row"><el-col :xs="24" :lg="13"><section class="panel"><div class="panel-head"><div class="panel-title"><span class="section-mark cyan-mark">◎</span><div><h2>AI 评价分析</h2><p>好评关键词、差评原因、售后风险和商品优化建议</p></div></div><el-tag type="info" effect="plain">{{ analysis.length }} 条记录</el-tag></div><div v-if="analysis.length" class="analysis-list"><article v-for="item in analysis" :key="item.id" class="analysis-item"><div class="item-top"><span class="product-label">商品 {{ item.productId }}</span><time>{{ formatTime(item.createTime) }}</time></div><h3>{{ item.summary || '暂无摘要' }}</h3><div class="tag-line"><el-tag v-for="tag in splitTags(item.positiveKeywords)" :key="tag" type="success" size="small">好评 {{ tag }}</el-tag><el-tag v-for="tag in splitTags(item.negativeReasons)" :key="'n'+tag" type="danger" size="small">风险 {{ tag }}</el-tag></div><p v-if="item.suggestions" class="suggestion">建议：{{ item.suggestions }}</p></article></div><div v-else class="empty-state"><div class="empty-icon">◎</div><h3>还没有评价分析</h3><p>当前已有 {{ reviewCount }} 条评价，但尚未生成 AI 分析记录。</p><el-button type="primary" plain @click="$router.push('/admin/center')">查看评价管理</el-button></div></section></el-col><el-col :xs="24" :lg="11"><section class="panel"><div class="panel-head"><div class="panel-title"><span class="section-mark blue-mark">▤</span><div><h2>运营增长报告</h2><p>结合评价、咨询与导购数据形成可执行建议</p></div></div><el-tag type="info" effect="plain">{{ reports.length }} 份报告</el-tag></div><div v-if="reports.length" class="report-list"><article v-for="report in reports" :key="report.id" class="report-item"><div class="item-top"><span class="period">{{ report.period || '运营周期未设置' }}</span><time>{{ formatTime(report.createTime) }}</time></div><h3>{{ report.title }}</h3><p>{{ report.content }}</p></article></div><div v-else class="empty-state"><div class="empty-icon report">▤</div><h3>暂无运营报告</h3><p>先积累评价和导购数据，再生成周期性增长报告。</p><div class="data-hint"><span>评价样本 <b>{{ reviewCount }}</b></span><span>分析记录 <b>{{ analysis.length }}</b></span></div><el-button plain @click="$router.push('/admin/center')">查看 AI 配置</el-button></div></section></el-col></el-row>
    <p class="footnote">数据来源：商品评价、售后咨询、AI 导购任务与推荐结果。页面不会虚构不存在的分析结果。</p>
  </div>
</template>
<script setup>
import { ref, computed, onMounted } from 'vue'
import { Refresh } from '@element-plus/icons-vue'
import request from '../../api/request'
const analysis=ref([]);const reports=ref([]);const reviews=ref([]);const loading=ref(false);const reviewCount=computed(()=>reviews.value.length)
function splitTags(value){return String(value||'').split(/[,，、\n]/).map(v=>v.trim()).filter(Boolean).slice(0,4)}function formatTime(value){return value?String(value).replace('T',' ').slice(0,16):'—'}
async function load(){loading.value=true;try{[analysis.value,reports.value,reviews.value]=await Promise.all([request.get('/admin/evaluation-analysis'),request.get('/admin/operation-reports'),request.get('/admin/reviews')])}finally{loading.value=false}}onMounted(load)
</script>
